<script setup>
import { computed, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useResource } from '../composables/useResource'
import { vehicleService } from '../services/vehicleService'
import { formatMoney, formatNumber, formatDistance, locationLabel, fuelLabel, transmissionLabel } from '../utils/format'
import VehicleGallery from '../components/VehicleGallery.vue'
import VehicleCard from '../components/VehicleCard.vue'
import ResultState from '../components/ResultState.vue'
import FutureAction from '../components/FutureAction.vue'
import LocationPanel from '../components/LocationPanel.vue'
import AppIcon from '../components/AppIcon.vue'
import FavoriteButton from '../components/FavoriteButton.vue'
import TransactionActions from '../components/TransactionActions.vue'
const route = useRoute(), { data, state, error, load } = useResource(), related = useResource()
const vehicle = computed(() => data.value?.data)
const specifications = computed(() => vehicle.value ? Object.entries({ Année: vehicle.value.year, Kilométrage: vehicle.value.mileage_km == null ? null : `${formatNumber(vehicle.value.mileage_km)} km`, Carburant: fuelLabel[vehicle.value.fuel], Transmission: transmissionLabel[vehicle.value.transmission], Moteur: vehicle.value.engine, Puissance: vehicle.value.horsepower ? `${vehicle.value.horsepower} ch` : null, Couleur: vehicle.value.color, Portes: vehicle.value.doors, Places: vehicle.value.seats, Condition: { new: 'Neuf', used: 'Occasion' }[vehicle.value.condition], Catégorie: vehicle.value.category?.label }).filter(([, value]) => value != null && value !== '') : [])
async function reload() {
  await load(signal => vehicleService.detail(route.params.slug, signal))
  if (state.value !== 'success') return
  document.title = `${vehicle.value.brand.name} ${vehicle.value.model.name} ${vehicle.value.year} à ${locationLabel(vehicle.value.location)} | BolideMarket`
  related.load(signal => vehicleService.list({ category: vehicle.value.category.slug, per_page: 5, ...(route.query.listing_type ? { listing_type: route.query.listing_type } : {}) }, signal))
}
watch(() => route.params.slug, reload, { immediate: true })
</script>
<template><div class="container page-content"><nav class="breadcrumbs" aria-label="Fil d’Ariane"><RouterLink to="/vehicles">Catalogue</RouterLink><span>/</span><span>{{ vehicle ? `${vehicle.brand.name} ${vehicle.model.name}` : 'Véhicule' }}</span></nav><ResultState :state="state" :error="error" @retry="reload"><template v-if="vehicle"><div class="detail-grid"><div><VehicleGallery :vehicle="vehicle" /><section class="content-panel"><p class="eyebrow">EN DÉTAIL</p><h2>Caractéristiques</h2><dl class="spec-grid"><div v-for="[label, value] in specifications" :key="label"><dt>{{ label }}</dt><dd>{{ value }}</dd></div></dl></section><section v-if="vehicle.description" class="content-panel"><h2>À propos de ce véhicule</h2><p class="description">{{ vehicle.description }}</p></section><section v-if="vehicle.features?.length" class="content-panel"><h2>Équipements</h2><ul class="feature-grid"><li v-for="feature in vehicle.features" :key="feature.id"><AppIcon name="check" />{{ feature.label || feature.name }}</li></ul></section><LocationPanel :location="vehicle.location" /></div><aside class="detail-summary"><div class="summary-panel"><div class="badge-row"><span v-if="vehicle.sale_price" class="pill">À vendre</span><span v-if="vehicle.rental_daily_price" class="pill">À louer</span><span v-if="vehicle.is_certified" class="certified"><AppIcon name="shield" />Certifié</span></div><h1>{{ vehicle.brand.name }} {{ vehicle.model.name }}</h1><p>{{ [vehicle.trim, vehicle.year].filter(Boolean).join(' · ') }}</p><p class="muted">{{ locationLabel(vehicle.location) }}<span v-if="vehicle.distance_km != null"> · {{ formatDistance(vehicle.distance_km) }}</span></p><p class="availability">{{ { available: 'Disponible', sold: 'Vendu', rented: 'Loué', other: 'Indisponible' }[vehicle.inventory_status] }}</p><div v-if="vehicle.sale_price" class="price-block"><small>Prix de vente</small><p>{{ formatMoney(vehicle.sale_price) }}</p><TransactionActions :vehicle="vehicle" type="buy" /></div><div v-if="vehicle.rental_daily_price" class="price-block"><small>Tarif de location</small><p>{{ formatMoney(vehicle.rental_daily_price) }} <small>/ jour</small></p><TransactionActions :vehicle="vehicle" type="reserve" /></div><p class="help">La disponibilité est vérifiée lors de votre demande. Confirmation du professionnel requise.</p><FavoriteButton :vehicle="vehicle" /><p v-if="vehicle.is_demo" class="demo-note">{{ vehicle.demo_notice }}</p><small class="reference">Réf. {{ vehicle.reference }}</small></div><section v-if="vehicle.shop" class="seller-panel"><p class="eyebrow">VOTRE PROFESSIONNEL</p><h2>{{ vehicle.shop.name }}</h2><p v-if="vehicle.shop.merchant?.is_verified" class="certified"><AppIcon name="shield" />Professionnel vérifié</p><p>{{ vehicle.shop.address }}</p><p>{{ locationLabel(vehicle.shop.location) }}</p><p v-if="vehicle.shop.published_vehicles_count != null">{{ vehicle.shop.published_vehicles_count }} véhicules publiés</p><RouterLink class="button full" :to="`/shops/${vehicle.shop.slug}`">Voir la boutique <AppIcon /></RouterLink><FutureAction label="Contacter le professionnel" /></section></aside></div><section class="related-section"><div class="section-heading"><div><p class="eyebrow">POURSUIVEZ VOTRE RECHERCHE</p><h2>Vous pourriez aussi aimer</h2></div><RouterLink to="/vehicles">Tout le catalogue →</RouterLink></div><p v-if="related.state.value === 'error'" class="help">Les suggestions ne sont pas disponibles pour le moment.</p><p v-if="related.state.value === 'success' && !(related.data.value?.data || []).some(item => item.id !== vehicle.id)" class="help">Aucune autre offre similaire pour le moment.</p><div class="vehicle-grid related-grid"><VehicleCard v-for="item in (related.data.value?.data || []).filter(item => item.id !== vehicle.id).slice(0, 4)" :key="item.id" :vehicle="item" :intention="route.query.listing_type" /></div></section></template></ResultState></div></template>
